  const BASS_STUFEN = [0, 2, 3, 4, 6, 5, 1];
  /* Reihenfolge der Bass-Zeilen im Raster, von hoch nach tief */
  const BASS_ANZEIGE = [4, 5, 3, 2, 1, 6, 0];
